INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (37054, '无情的瓜果破坏者是所有园丁的噩梦。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
