INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (48676, '似龙非龙、似马非马。好战而令人畏惧，只有强者才能驾驭。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
