INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (49000, '在这个挑战中，等级的提高真正与猪相关——只能通过击杀野猪获取经验！') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (49990, '他是老死的。说真的。别那样看我们。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- He died of old age. Seriously. Stop looking at us like that.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (49991, '甲壳护肩。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Shell-shielded shoulders.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (49995, '炫光魅影是能帮你打造全新风格的首席地精造型师！在你投身战斗之前，它总能帮你精心装扮，让你以最佳状态亮相。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50034, '跪拜在他的面前。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- 
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50038, '大胆张扬，为有格调的法师而设。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Bold, for mages with flair.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50044, '金色，略带奢华气息。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Golden, with a touch of luxury.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50050, '斯皮迪的一点心意，让你旅途安稳。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A little something from Speedy to keep you steady on your journey.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50051, '保持节奏！斯皮迪会奖励你的坚持。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Keep up the pace! Speedy rewards your persistence.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50052, '慢而稳者赢得竞赛——这份礼物就是证明。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Slow and steady wins the race — here's a gift to prove it.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50053, '你做得很好！斯皮迪会在你前行时支持你。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- You're doing great! Speedy's got your back as you push forward.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50054, '耐心是美德，斯皮迪的奖励便是证明。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Patience is a virtue, and Speedy's rewards are proof.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50055, '恭喜！慢而稳者果真获胜——享受你应得的奖励吧。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Congratulations! Slow and steady truly wins — enjoy your well-earned prize.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50086, '激流堡的传承仍在延续。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- The legacy of Stromgarde lives on.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50087, '向海军部宣誓效忠者的颜色。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- The colors of those who've sworn fealty to the Admiralty.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50088, '坚韧如塞拉摩本身。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Resilient like Theramore itself.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50089, '一件未经许可的达拉然纪念品。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- An unapproved souvenir from Dalaran.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50090, '暴风城的纯洁，以纪念王国英勇的阵亡者。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Stormwind's purity, in honor of the Kingdom's brave fallen heroes.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50091, '幽暗神秘，带着禁忌欲望的气息。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Dark and mysterious, with the scent of forbidden desire.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50092, '赤红之色，怀炽烈之志。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Crimson with a fiery purpose.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50093, '壁炉谷的战旗，由守卫其圣地的信徒佩戴。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A banner of Hearthglen, worn by the faithful who defend its holy grounds.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50107, '叶绿色，献给愿更像大自然树妖的人。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Leaf green, for those who wish to be more like the dryads of the Great Outdoors.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50108, '沉静的冷绿色，献给愿映照自然之魂的精灵。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- The quiet cool green, for the elf who wishes to reflect nature's spirit.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50109, '引导你内心的德鲁伊……哦，该小睡一会儿了……') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Channel your inner druid...oooh, time for a nap...
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50110, '水蓝色如月亮井的水，宁静却藏着秘密。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Aqua blue like the waters of the Moonwell, calming yet hiding secrets.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50111, '与流行看法相反，白发并不能帮你判断暗夜精灵的年龄。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Contrary to popular belief, white hair does not help with telling the age of a Night Elf.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50112, '蓝如灰谷上空的天空，满是神秘与古老智慧。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Blue as the skies above Ashenvale, filled with both mystery and ancient wisdom.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50113, '深暗蓝色，正适合永恒星光之地。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Deep dark blue, perfect for the land of eternal starlight.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50114, '鲜活的紫色，清新如花！') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A vibrant purple, fresh as a flower!
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50115, '暗如值夜守卫站了12小时后的心情。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Dark as a night shift guard's mood after 12 hours of standing still.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50116, '根据光线与性别，呈深赤褐色或普通棕色。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Deep auburn-red or regular brown depending on the lighting and gender.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50117, '铜棕色。无论你只是采矿，还是在剥夺当地狗头人的蜡烛，都很完美。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Coppery Brown. Perfect whether you're just mining or depriving local kobolds of candles.”
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50118, '明亮的火红色。嗯，够辣！') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Bright flame red. Mm, spicy!”
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50119, '深沉的抛光红金色。总比清醒着好，对吧？') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Deep burnished red-gold. Better than being sober, isn't it?
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50120, '纯正的金金色，明亮闪耀如大教堂广场屋顶上的朝阳。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- True golden blonde, bright and shining like the rising sun on the Cathedral Square roofs.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50121, '耀眼的阳光黄。你还记得阳光长什么样吧？') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Brilliant sunshine yellow. You do remember what sunshine looks like, right?
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50122, '灰金色。如西部荒野的收成，只是没有腰酸背痛。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Ash blonde. Like Westfall's harvest, minus the back pain.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50123, '钢铁般的灰色，如经历太多战役、太少沐浴的骑士。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A steely grey, like the knight who's seen too many battles and too few baths.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50124, '高贵的银色，愈久愈佳。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A distinguished silver that just gets better with age.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50125, '黑如你上一次“可控”爆炸。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Black as your last “controlled” explosion.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50126, '棕色，如你酒后事故的现场。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Brown, like the aftermath of your brew-fueled accidents.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50127, '金色，闪亮，有点过于耀眼。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Blonde, shiny, and a little bit too bright.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50128, '虹彩蓝白色。让人想起各种导电液体。肯定没用它们做这个。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Iridescent blue-white. Reminds you of various conductive liquids. Surely they weren't used
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50129, '深黑色，如你要挖到时间尽头的坑道。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Deep black, like the tunnels you'll be digging 'til the end of time.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50130, '红艳、火辣，绝不退款。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Red, hot, and totally non-refundable.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50131, '淡银蓝色，如你最新“创新”点子迸出的火花。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Pale silvery blue, like the sparks from your latest “innovative” idea.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50132, '绿色，据说是麻风侏儒中的最新流行。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Green, said to be the latest hit among Leper Gnomes.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50133, '他们也许会嘲笑你的粉发，但你知道下次发明家集市上你会抢尽风头。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- They may laugh at your pink hair, but you'll know you will steal the spotlight with this a
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50134, '纯正的橙色。比熔炉更热，也更顽固两倍。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- True orange. Hotter than the forge and twice as stubborn.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50135, '金色而强劲，如让矮人整夜战斗的麦酒。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Golden and strong, like the ale that keeps dwarves fighting all night.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50136, '火红色！比矮人被你动胡子时的脾气还烫。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Fiery red! Burns hotter than a dwarf's temper when you mess with his beard.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50137, '浅灰色，如矿坑中的岩石，也同样坚硬。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Light Grey as the rocks in the pits, and just as tough.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50138, '赤褐色。如历经百年血战的战斧般锈蚀。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Auburn brown. Rusty as a war axe after a hundred years of bloodshed.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50140, '不算金色，也不算棕色。也许喝几杯就能帮你决定了……') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Not quite blonde, not quite brown. Maybe a few drinks would help you decide...
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50141, '纯正的银灰色。坚如钢铁，硬如我们开凿的山脉。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- True silver-grey. Hard as steel, tough as the mountains we carve into.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50142, '深灰烬色，如历经太多战事的矮人战士风化的皮革。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Deep Ash Grey like the weathered hides of dwarven warriors who've seen too many wars.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50143, '看着高贵，行如君王。或者被诅咒。随你选。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Look royal, act like a king. Or get cursed. Your choice.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50144, '血红。随时备战。或者只是愤怒……无论如何，你都会是个像样的狂战士。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Blood red. Battle-ready. Or just angry… either way, you'll make a convincing berserker.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50145, '比沙漠中巨魔的脾气还火。佩戴风险自负。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Hotter than a troll's temper in a desert. Wear at your own risk.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50146, '闪亮得让巨魔与灵魂为之争斗。诅咒不予退款。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Shiny enough to make trolls and spirits fight over it. Curses are not refundable.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50147, '绿如丛林……满是蛇、虫子，和糟糕的决定。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Green as the jungle… full of snakes, bugs, and bad decisions.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50148, '清凉如水，锋利如下方潜伏的生物。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Cool as the waters, sharp as the creatures lurking below.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50149, '如波涛一般，但一步走错你就会成为洛阿的盛宴。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Like the waves, but one wrong move and you'll be a feast for the loa.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50150, '暗如海洋深处。别问下面有什么。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Dark as the ocean's depths. Don't ask what's down there.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50151, '灰如玩弄巫毒巨魔的灵魂。佩戴风险自负。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Grey like the souls of trolls who messed with voodoo. Wear at your own risk.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50152, '白如雪，冷如偷你毯子的巨魔。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- White as snow, cold as the troll who'll steal your blanket.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50153, '黑蓝色，如你在酒馆又一场斗殴后的脸。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Black-blue, like your face after another brawl at the tavern.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50154, '棕色，结实，如战歌峡谷的树木。强壮，如我们。也许更强。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Brown, sturdy, like the trees in Warsong Gulch. Strong, like us. Maybe stronger.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50155, '深覆盆子红紫色，如那些念叨世界末日的诡异教徒的长袍。又来一次。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Deep raspberry red-violet, like the robes of those creepy cultists chanting about the end 
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50156, '深沉的暖紫色，如巨魔的战旗。漂亮，但随时准备战斗。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A deep warm purple like the banners of the trolls. Pretty, but ready for battle.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50157, '深沉的冷紫色，如你签下那份契约后的灵魂。邪恶从未如此好看。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Deep cool violet like your soul after signing that contract. Evil never looked so good.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50158, '暗如黑石山，比表亲的脑袋还硬。穿上，或者闭嘴。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Dark as Blackrock, tougher than your cousin's skull. Wear it, or shut up.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50159, '灰如战后的土地。受不了就回你的洞穴去。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Grey like the land after war. If you can't handle it, go back to your cave.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50160, '苍白，灰扑扑，如德拉诺的最后残余。这是我们仅剩的，自豪地穿上吧。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Pale, dusty, like the last remnants of Draenor. It's all we got left, so wear it proudly.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50161, '黯淡的幽绿色，如你灵魂的微光……或者根本没有。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A dull ghostly green like the glow of your soul… or lack of it.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50162, '死寂的红紫色——如坟前玫瑰的一吻。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- A dead red-violet- like a kiss from a rose on a grave.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50163, '棕如夺走我们所有人的瘟疫。拥抱它，正如我们拥抱死亡。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Brown as the Plague that took us all. Embrace it, like we embraced death.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50164, '金色，如果你能这么叫的话。暗沉。惨白，如我们的头发……和我们的生活。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Blonde, if you can call it that. Dark. Ghastly, like our hair... and our lives.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50165, '金色，但更……灰白。如你在墓中待太久后的皮肤。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Blonde, but more... ashen. Like your skin after too long in the grave.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50166, '蓝如你的血。冰冷。死寂。被遗忘者的完美色调。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Blue like your blood. Cold. Dead. A perfect shade for the Forsaken.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50167, '深绿色。药剂师中的最新流行。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Dark green. The latest hit among the Apothecary.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50168, '青绿色，却是死的。就像我们游荡的土地。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Teal, but dead. Like the land we haunt.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50169, '紫色，却已腐烂。制作这种色调没有使用任何身体部位。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Purple, but rotten. No body parts were used in creating this shade.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50170, '黑如我们的心。腐如我们继承的世界。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- Black as our hearts. Rotten as the world we've inherited.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50256, '刀刃有缺口。它的主人也是。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- The blade's chipped. So was its owner.
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (50257, '这本书似乎被翻阅过很多次。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);  -- This book seems well used.
